drills.solution:
export function memoize(fn) {
  const cache = new Map();
  return (arg) => {
    if (!cache.has(arg)) cache.set(arg, fn(arg));
    return cache.get(arg);
  };
}

tests.code:
assert.equal(typeof mod.memoize, 'function', 'export memoize');
let calls = 0;
const sq = mod.memoize((n) => { calls++; return n * n; });
assert.equal(sq(4), 16);
assert.equal(sq(4), 16);
assert.equal(calls, 1);

let calls = 0;
const sq = mod.memoize((n) => { calls++; return n * n; });
assert.equal(sq(2), 4);
assert.equal(sq(3), 9);
assert.equal(calls, 2);

const kind = mod.memoize((v) => typeof v);
assert.equal(kind(0), 'number');
assert.equal(kind('0'), 'string');

let calls = 0;
const f = mod.memoize(() => { calls++; return undefined; });
f(1);
f(1);
assert.equal(calls, 1);

let calls = 0;
const f = mod.memoize(() => ++calls);
f(NaN);
f(NaN);
assert.equal(calls, 1);

drills.explanation:
A `Map` in the closure, checked with `has` (not with the stored value):

```js
export function memoize(fn) {
  const cache = new Map();
  return (arg) => {
    if (!cache.has(arg)) cache.set(arg, fn(arg));
    return cache.get(arg);
  };
}
```

A plain object cache fails the test "0 and '0' are different keys", because object keys are converted to strings and `cache[0]` is `cache['0']`. Checking `cache.get(arg) === undefined` instead of `has` fails "an undefined result is still cached (boundary)": a stored undefined looks like a miss and `fn` runs again. Keeping keys in an array and searching it with `indexOf` fails "NaN is found again", since `indexOf` compares with `===`; a `Map` uses SameValueZero, which matches NaN.
